(()=>{const run=()=>{const home=document.getElementById('home');if(!home||document.getElementById('mindfulness-complete-20260825'))return;const card=document.createElement('div');card.className='card';card.id='mindfulness-complete-20260825';card.style.marginBottom='16px';card.innerHTML='<span class="pill">25 AUG · DONE</span><h3 style="margin-top:.7rem">Mindfulness homework completed</h3><p>Did meditation tonight and completed the Chocolate Meditation using favourite Hotel Chocolat chocolate.</p><p><strong>Values showing up:</strong> peace, health without obsession, and living again. After a stressful work day, I still made space to slow down and actually experience something I enjoy.</p><p><a href="https://franticworld.com/free-meditations-from-mindfulness/" target="_blank" rel="noopener noreferrer">Mindfulness meditation exercises used for this homework</a></p>';const hero=home.querySelector('.hero');if(hero)hero.insertAdjacentElement('afterend',card);};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(run,1200),{once:true});else setTimeout(run,1200);})();